import 'package:equatable/equatable.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:locallink/core/bloc/bloc_utils.dart';import 'package:locallink/core/models/account_transfer.dart';import 'package:locallink/features/connectivity/data/models/discovered_server.dart';import 'package:locallink/features/transfer/domain/account_transfer_repository_contract.dart';
final class AccountTransferScanState extends Equatable{final AccountTransferPayload? payload;final bool processing,revokeSource;final String? error,serverStatus;const AccountTransferScanState({this.payload,this.processing=false,this.revokeSource=true,this.error,this.serverStatus});AccountTransferScanState copyWith({AccountTransferPayload? payload,bool? processing,bool? revokeSource,String? error,bool clearError=false,String? serverStatus,bool clearServerStatus=false,bool clearPayload=false})=>AccountTransferScanState(payload:clearPayload?null:(payload??this.payload),processing:processing??this.processing,revokeSource:revokeSource??this.revokeSource,error:clearError?null:(error??this.error),serverStatus:clearServerStatus?null:(serverStatus??this.serverStatus));@override List<Object?>get props=>[payload,processing,revokeSource,error,serverStatus];}
final class AccountTransferScanBloc extends Cubit<AccountTransferScanState>{final AccountTransferRepositoryContract repository;AccountTransferScanBloc(this.repository):super(const AccountTransferScanState());AccountTransferPayload? get payload=>state.payload;bool get processing=>state.processing;bool get revokeSource=>state.revokeSource;String? get error=>state.error;String? get serverStatus=>state.serverStatus;void setRevokeSource(bool v)=>emit(state.copyWith(revokeSource:v));bool acceptPayload(AccountTransferPayload p){if(state.processing||state.payload!=null)return false;if(!p.expiresAt.isAfter(DateTime.now())){emit(state.copyWith(error:'This transfer QR has expired. Generate a new QR on the old phone.'));return false;}emit(state.copyWith(payload:p,clearError:true));return true;}void clearError(){if(state.error!=null)emit(state.copyWith(clearError:true));}Future<bool> findAndComplete({required String manualServer,required String deviceName})async{final p=state.payload;if(p==null)return false;emit(state.copyWith(processing:true,clearError:true,serverStatus:'Finding the matching LocalLink server…'));final candidates=<String>{};try{final found=await repository.discoverServers();candidates.addAll(found.map((DiscoveredServer e)=>e.address));}catch(_){}if(manualServer.trim().isNotEmpty)candidates.add(manualServer.trim());if(candidates.isEmpty){emit(state.copyWith(processing:false,clearServerStatus:true,error:'No LocalLink server was found. Enter the server address and try again.'));return false;}String? matched;for(final a in candidates){try{final info=await repository.verifyServer(a);if(info.serverId==p.serverId&&info.fingerprint.toUpperCase()==p.fingerprint.toUpperCase()){matched=repository.normalizeServerAddress(a);break;}}catch(_){} }if(matched==null){emit(state.copyWith(processing:false,clearServerStatus:true,error:'The QR belongs to a different or unavailable LocalLink server.'));return false;}try{emit(state.copyWith(serverStatus:'Completing secure device transfer…'));await repository.complete(server:matched,payload:p,deviceName:deviceName,revokeSourceDevice:state.revokeSource);emit(state.copyWith(processing:false));return true;}catch(e){emit(state.copyWith(processing:false,clearServerStatus:true,error:cleanBlocError(e)));return false;}}}
